    from math import sqrt
    from itertools import combinations_with_replacement

    def is_product_sum(num, k):
        for i in range(2, int(sqrt(num)) + 1):
            if num % i == 0:
                factors = [i, num // i]
                if len(factors) == k:
                    return True
                for combo in combinations_with_replacement(factors, k - 2):
                    if sum(combo) + i + num // i == num:
                        return True
        return False

