def count_subsequences(needle, haystack):
    n = len(needle)
    m = len(haystack)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(m + 1):
        dp[0][i] = 1
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = dp[i][j - 1]
            if needle[i - 1] == haystack[j - 1]:
                dp[i][j] += dp[i - 1][j - 1]
    return dp[n][m] % 100000000
